import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.CZxGLIO_.js";const h=JSON.parse('{"title":"GooseForum","description":"Practical GooseForum guides.","frontmatter":{"title":"GooseForum","description":"Practical GooseForum guides."},"headers":[],"relativePath":"en/docs/gooseforum/index.md","filePath":"en/docs/gooseforum/index.md"}'),i={name:"en/docs/gooseforum/index.md"};function n(d,e,s,c,u,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="gooseforum" tabindex="-1">GooseForum <a class="header-anchor" href="#gooseforum" aria-label="Permalink to &quot;GooseForum&quot;">​</a></h1><p>GooseForum is a Go and React 19 community platform with Markdown topics, replies, categories, notifications and administration. SQLite is the default; MySQL, PostgreSQL and S3 storage are optional. Production frontend resources are embedded in one executable.</p><p>These guides were checked against release <strong>v0.2.122</strong>, commit <code>3044207</code>, on 2026-11-15. They describe implemented behavior; deployment service files are suggested operational examples.</p><h2 id="reading-path" tabindex="-1">Reading path <a class="header-anchor" href="#reading-path" aria-label="Permalink to &quot;Reading path&quot;">​</a></h2><p>New site: installation → initial administration → account security → deployment. Existing site: review configuration, back up before upgrading, then verify recovery. Use troubleshooting when a specific operation fails.</p><table tabindex="0"><thead><tr><th>Guide</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="./installation/">Installation and first start</a></td><td>Release archives, source builds and first registration</td></tr><tr><td><a href="./administration/">Initial administration</a></td><td>Email, categories, permissions and third-party login</td></tr><tr><td><a href="./configuration/">Configuration reference</a></td><td>TOML, databases, storage and runtime settings</td></tr><tr><td><a href="./security/">Registration and account security</a></td><td>Quotas, trusted proxies, MFA and recovery codes</td></tr><tr><td><a href="./deployment/">Production deployment</a></td><td>systemd, Caddy, HTTPS and verification</td></tr><tr><td><a href="./maintenance/">Backup, upgrades and recovery</a></td><td>Backup scope, migrations, recovery and rollback</td></tr><tr><td><a href="./troubleshooting/">Troubleshooting</a></td><td>Startup, mail, attachments, accounts and updates</td></tr></tbody></table><hr><p>Sources checked on 2026-11-15：<a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/README_ZH.md" target="_blank" rel="noreferrer">Source</a>。</p>',8)])])}const p=t(i,[["render",n]]);export{h as __pageData,p as default};
